void bm_read_keys(void (*cb)(char **key, int m))
{
    char **key;
    int max = 8, m = 0;
    key = malloc(sizeof(*key) * max);
    for (;;)
    {
        char *s = 0;
        size_t n;
        ssize_t len = getline(&s, &n, stdin);
        if (feof(stdin))
            break;
        if (len == -1)
            perror("getline"), exit(1);
        if (s[len - 1] == '\n')
            s[len - 1] = 0;
        key[m++] = s;
        if (m == max)
            max *= 2, key = realloc(key, sizeof(*key) * max);
    }
    for (int i = m - 1; i > 1; i--)
    {
        int j = random() % i;
        char *tmp = key[i];
        key[i] = key[j];
        key[j] = tmp;
    }
    cb(key, m);
}

