BLT_IT *blt_setp(BLT *blt, char *key, int *is_new)
{
    BLT_IT *p = confident_get(blt, key);
    if (!p)
    {
        blt->empty = 0;
        BLT_IT *leaf = (BLT_IT *)blt->root;
        leaf->key = strdup(key);
        leaf->data = 0;
        if (is_new)
            *is_new = 1;
        return leaf;
    }
    for (char *c = key, *pc = p->key;; c++, pc++)
    {
        uint8_t x = *c ^ *pc;
        if (x)
        {
            blt_node_ptr n = malloc(2 * sizeof(*n));
            x = to_mask(x);
            BLT_IT *leaf = (BLT_IT *)n;
            blt_node_ptr other = n;
            if (*c & x)
                leaf++;
            else
                other++;
            leaf->key = strdup(key);
            leaf->data = 0;
            int byte = c - key;
            blt_node_ptr p = (blt_node_ptr)blt->root;
            while (p->is_internal)
            {
                if ((byte << 8) + p->mask < (p->byte << 8) + x)
                    break;
                p = follow(p, key);
            }
            *other = *p;
            p->byte = byte;
            p->mask = x;
            p->kid = n;
            p->is_internal = 1;
            if (is_new)
                *is_new = 1;
            return leaf;
        }
        if (!*c)
        {
            if (is_new)
                *is_new = 0;
            return p;
        }
    }
}

