functions.blt_allprefixed:
int blt_allprefixed(BLT *blt, char *key, int (*fun)(BLT_IT *))
{
    if (blt->empty)
        return 1;
    blt_node_ptr p = blt->root, top = p;
    int keylen = strlen(key);
    while (p->is_internal)
    {
        if (p->byte >= keylen)
        {
            p = p->kid;
        }
        else
        {
            p = follow(p, key);
            top = p;
        }
    }
    if (strncmp(key, ((BLT_IT *)p)->key, keylen))
        return 1;
    int traverse(blt_node_ptr p)
    {
        if (p->is_internal)
        {
            int status = traverse(p->kid);
            if (status != 1)
                return status;
            status = traverse(p->kid + 1);
            if (status != 1)
                return status;
            return 1;
        }
        return fun((BLT_IT *)p);
    }
    return traverse(top);
}

