                t00->right = sibling;
            }
        }
        free(t0);
    }
    if (p->next)
        p->next->prev = p->prev;
    else
        cbt->last = p->prev;
    if (p->prev)
        p->prev->next = p->next;
    else
        cbt->first = p->next;
    free(p->key);
    void *data = p->data;
    free(p);
    return data;
}

functions.clear_recurse:
static void clear_recurse(cbt_node_ptr t, void (*fn)(void *, const void *))
{
    if (EXT == t->crit)
    {
        cbt_leaf_ptr p = (cbt_leaf_ptr)t;
        if (fn)
            fn(p->data, p->key);
        free(p->key);
        free(p);
        return;
    }
    clear_recurse(t->left, fn);
    clear_recurse(t->right, fn);
    free(t);
}

functions.cbt_remove_all_with:
void cbt_remove_all_with(cbt_t cbt, void (*fn)(void *data, const void *key))
{
    if (cbt->root)
    {
        clear_recurse(cbt->root, fn);
        cbt->root = 0;
        cbt->count = 0;
        cbt->first = cbt->last = 0;
    }
}

functions.cbt_forall:
void cbt_forall(cbt_t cbt, void (*fn)(cbt_it))
{
    cbt_leaf_ptr p;
    for (p = cbt->first; p; p = p->next)
        fn(p);
}

functions.cbt_forall_at:
void cbt_forall_at(cbt_t cbt, void (*fn)(void *data, const void *key))
{
    cbt_leaf_ptr p;
    for (p = cbt->first; p; p = p->next)
        fn(p->data, p->key);
}

functions.cbt_overhead:
size_t cbt_overhead(cbt_t cbt)
{
    size_t n = sizeof(struct cbt_s);
    if (!cbt->root)
        return n;
    void add(cbt_node_ptr p)
    {
        if (p->crit == EXT)
        {
            n += sizeof(struct cbt_leaf_s);
        }
        else
        {
            n += sizeof(struct cbt_node_s);
            add(p->left);
            add(p->right);
        }
    }
    add(cbt->root);
    return n;
}
